mapper.select:
SELECT FROM ultary_tag WHERE is_deleted = 0
AND ( hashtag LIKE CONCAT(#{q}, '%') OR IFNULL(handle, '') LIKE CONCAT(#{q}, '%') OR (profile_status = 'APPROVED' AND IFNULL(title, '') LIKE CONCAT('%', #{q}, '%')) )
ORDER BY use_count DESC, tag_id DESC LIMIT #{limit}

SELECT COUNT(1)
FROM ultary_tag
WHERE handle = #{handle}
  AND is_deleted = 0

	AND tag_id != #{excludeTagId}

mapper.insert:
INSERT INTO ultary_tag_image (
	tag_id,
	file_id,
	sort_order
) VALUES (
	#{tagId},
	#{fileId},
	#{sortOrder}
)

mapper.select:
SELECT 
FROM ultary_tag_profile_request r
JOIN ultary_tag t ON t.tag_id = r.tag_id
WHERE 1 = 1

	AND r.requester_user_no = #{requesterUserNo}


	AND r.status = #{status}

ORDER BY r.tag_profile_request_id DESC
LIMIT #{limit}

mapper.insert:
INSERT INTO ultary_tag_profile_request_image (
	tag_profile_request_id,
	file_id,
	sort_order
) VALUES (
	#{tagProfileRequestId},
	#{fileId},
	#{sortOrder}
)
